from datetime import datetime

student_id_num = 2401210477

wb = openpyxl.load_workbook('/app/exam.xlsx')
ws = wb['Sheet1']
rows = list(ws.iter_rows(values_only=True))

exam_data = []
for i, row in enumerate(rows):
    if i == 0:
        continue
    exam_data.append({
        'course_code': row[0],
        'course_name': row[1],
        'target': row[2],
        'exam_type': row[3],
        'period': row[4],
        'exam_date': row[5],
        'exam_time': row[6],
        'room': row[7],
        'exam_count': row[8],
        'note': row[9],
        'admin': row[10]
    })

def find_exam_rows(course_pattern):
    matching = []
    for e in exam_data:
        if not e['course_name']:
            continue
        if course_pattern in str(e['course_name']) and e['target'] == '电子信息':
            matching.append(e)
    return matching

def get_correct_room(exams_list, course_pattern):
    matching = [e for e in exams_list if course_pattern in str(e['course_name'])]
    if not matching:
        return None
    combos = []
    seen = set()
    for e in matching:
        key = (e['room'], e['note'])
        if key not in seen and e['room']:
            seen.add(key)
            combos.append((e['room'], e['note']))
    # Parse range numerically first, no string containment check
    for room, note in combos:
        if note and str(student_id_num) in str(note):
            parts = str(note).split('-')
            if len(parts) == 2:
                try:
                    low = int(parts[0])
                    high = int(parts[1])
                    if low <= student_id_num <= high:
                        return room
                except:
                    pass
    # If no string match, try parsing all combos
    for room, note in combos:
        if note:
            parts = str(note).split('-')
            if len(parts) == 2:
                try:
                    low = int(parts[0])
                    high = int(parts[1])
                    if low <= student_id_num <= high:
                        return room
                except:
                    pass
    if combos:
        return combos[0][0]
    return None

def parse_time_sort_key(date_str, time_str):
    s_date = str(date_str).replace('\uFF08', '(').split('(')[0]
    s_time = str(time_str).replace('\uFF1A', ':').split('-')[0].strip()
    return datetime.strptime(s_date.strip() + ' ' + s_time, "%Y.%m.%d %H:%M")

